    dev_sigma[1 * nvoxels + ell] = C[1] * eps[1] + C[6] * eps[0] + C[8] * eps[2] + 2 * C[12] * eps[3] + 2 * C[13] * eps[4] + 2 * C[14] * eps[5];
    dev_sigma[2 * nvoxels + ell] = C[2] * eps[2] + C[7] * eps[0] + C[8] * eps[1] + 2 * C[15] * eps[3] + 2 * C[16] * eps[4] + 2 * C[17] * eps[5];
    dev_sigma[3 * nvoxels + ell] = 2 * C[3] * eps[3] + C[9] * eps[0] + C[12] * eps[1] + C[15] * eps[2] + 2 * C[18] * eps[4] + 2 * C[19] * eps[5];
