/* Compute stress sigma_{ij} = C_{ijkl} epsilon_{kl} for isotropic material */
void compute_stress_isotropic(float *__restrict__ dev_epsilon,
                              float *__restrict__ dev_sigma,
                              float *__restrict__ dev_lambda,
                              float *__restrict__ dev_mu,
                              const GridSpec grid_spec)
